-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- the guard blocks an ON override whenever the plan's own row is false
-- targets: c15
-- scopes: all
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._override_above_tier(
  p_feature_key text,
  p_min_tier    text,
  p_plan_tier   text,
  p_override    jsonb
)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = public
AS $$
  SELECT COALESCE((p_override ->> 'enabled')::boolean, true)
     AND EXISTS (SELECT 1 FROM public.plan_features pf JOIN public.plans p ON p.id = pf.plan_id
                  JOIN public.feature_definitions fd ON fd.id = pf.feature_id
                 WHERE p.tier = p_plan_tier AND fd.key = p_feature_key AND pf.enabled = false)
     -- AND p_feature_key = 'transaction_checklists'   -- the narrowing line (see header)
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public._override_above_tier(text,text,text,jsonb)'::regprocedure) LIKE '%pf.enabled = false%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('guard keyed on the plan row') AS mutation;
